#!/usr/bin/env bash
# EngineOS — generate slash-command entrypoints for every agent.
# One command per agent canonical name AND per alias, so users can invoke an
# agent directly with `/<name>` or `/<alias>`. Each command dispatches the agent
# via the Task tool with the user's text as the prompt; the agent self-infers its
# own mode (AUDIT/IMPLEMENT) per its definition.
#
# CUSTOMIZATION IS PRESERVED. Every file this script writes carries a "@generated"
# marker line. On each run:
#   - a file WITH the marker is (re)generated / refreshed;
#   - a file WITHOUT the marker is treated as hand-customized and left untouched.
# So to permanently customize a command, edit it and delete its marker line —
# the generator will never overwrite or delete it again.
#
# Stale files (whose agent/alias no longer exists) are removed only when they
# still carry the marker; customized orphans are kept and reported, never deleted.
#
# Re-run whenever agents are added/renamed/re-aliased. Usage: ./scripts/gen-agent-commands.sh
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
AGENTS_DIR="$ROOT/agents"
OUT_DIR="$ROOT/commands/agents"

MARKER="<!-- @generated by scripts/gen-agent-commands.sh — do not edit. To customize this command, delete this line and the generator will preserve your changes. -->"

[ -d "$AGENTS_DIR" ] || { echo "No agents dir at $AGENTS_DIR" >&2; exit 1; }
mkdir -p "$OUT_DIR"

GENERATED=0
PRESERVED=0
REMOVED=0
KEPT_ORPHAN=0
EXPECTED=$'\n'   # newline-delimited set of invoke names we own this run

frontmatter_value() { # field, file -> value (first match, after "field: ")
  grep -m1 "^$1:" "$2" | sed "s/^$1: //"
}

is_generated() { # file -> 0 if it carries our marker (safe to overwrite/remove)
  [ -f "$1" ] && grep -qF "$MARKER" "$1"
}

emit() { # invoke_name, agent_name, alias, description
  local invoke="$1" agent="$2" alias="$3" desc="$4"
  local out="$OUT_DIR/$invoke.md"
  EXPECTED="${EXPECTED}${invoke}"$'\n'

  if [ -f "$out" ] && ! is_generated "$out"; then
    echo "preserved (customized): $invoke.md" >&2
    PRESERVED=$((PRESERVED + 1))
    return
  fi

  cat > "$out" <<EOF
---
description: $desc
argument-hint: [task or question for the agent]
allowed-tools: Task
---
$MARKER

Dispatch the \`$agent\` agent (alias \`$alias\`) via the Task tool, passing
\`\$ARGUMENTS\` as its prompt. If \`\$ARGUMENTS\` is empty, ask the user what they
want the agent to do before dispatching.

The agent follows its own mode and output rules (it self-infers AUDIT vs
IMPLEMENT where applicable). Relay its report back verbatim; do not re-do its
work yourself.
EOF
  GENERATED=$((GENERATED + 1))
}

for f in "$AGENTS_DIR"/*.md; do
  name="$(frontmatter_value name "$f")"
  [ -n "$name" ] || { echo "skip (no name): $f" >&2; continue; }
  # Alias: from the frontmatter description's "Alias: <slug> (invocable by this
  # name)." — restricted to the frontmatter block (between the first two `---`
  # lines) so body prose can never be mistaken for an alias.
  alias="$(sed -n '/^---$/,/^---$/p' "$f" | grep -oiE 'Alias: [a-z0-9-]+' | head -1 | sed -E 's/[Aa]lias: //' || true)"
  desc="Invoke the $name agent${alias:+ (alias $alias)}."

  emit "$name" "$name" "${alias:-$name}" "$desc"
  if [ -n "$alias" ] && [ "$alias" != "$name" ]; then
    emit "$alias" "$name" "$alias" "$desc"
  fi
done

# Prune stale entrypoints — but only ones we generated. Never touch customized files.
for out in "$OUT_DIR"/*.md; do
  [ -e "$out" ] || continue
  base="$(basename "$out" .md)"
  printf '%s' "$EXPECTED" | grep -qxF "$base" && continue
  if is_generated "$out"; then
    rm -f "$out"
    echo "removed stale: $base.md" >&2
    REMOVED=$((REMOVED + 1))
  else
    echo "kept orphaned customized (agent removed/renamed?): $base.md" >&2
    KEPT_ORPHAN=$((KEPT_ORPHAN + 1))
  fi
done

echo "Done in $OUT_DIR — generated: $GENERATED, preserved: $PRESERVED, removed stale: $REMOVED, kept orphaned customized: $KEPT_ORPHAN"
